#!/usr/bin/env node

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const TSX = path.join(ROOT, 'src/features/landing/LandingPage.tsx');
const CSS = path.join(ROOT, 'src/features/landing/landing-page.css');
const ASSET_DIR = path.join(ROOT, 'src/features/landing/assets');
const LOGO = path.join(ASSET_DIR, 'opfg-logo-mark.png');

const LOGO_BASE64 = '';

function fail(message) {
  console.error(`\n[landing-rework] ERROR: ${message}\n`);
  process.exit(1);
}

function read(file) {
  if (!fs.existsSync(file)) {
    fail(`Missing file: ${path.relative(ROOT, file)}`);
  }

  return fs.readFileSync(file, 'utf8');
}

function write(file, content) {
  fs.writeFileSync(file, content.replace(/\r?\n/g, '\n'), 'utf8');
  console.log(`[landing-rework] updated ${path.relative(ROOT, file)}`);
}

function ensureReactHooks(source) {
  const match = source.match(/import\s*\{([^}]*)\}\s*from 'react';/);
  if (!match) fail("Could not find the named React import in LandingPage.tsx.");

  const hooks = match[1]
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);

  for (const hook of ['useLayoutEffect', 'useMemo', 'useRef', 'useState']) {
    if (!hooks.includes(hook)) hooks.push(hook);
  }

  const formatted = `import {\n${hooks
    .sort()
    .map((hook) => `  ${hook},`)
    .join('\n')}\n} from 'react';`;

  return source.replace(match[0], formatted);
}

function ensureLogoImport(source) {
  if (source.includes("import logoMark from './assets/opfg-logo-mark.png';")) {
    return source;
  }

  const anchor =
    "import { notifyUiLocaleChanged } from '@/features/settings/localeSync';";

  if (!source.includes(anchor)) {
    fail('Could not find localeSync import anchor.');
  }

  return source.replace(
    anchor,
    `${anchor}\nimport logoMark from './assets/opfg-logo-mark.png';`,
  );
}

function ensureViewportFitHook(source) {
  const marker = '// OPFG landing viewport fit';
  if (source.includes(marker)) return source;

  const statePattern =
    /(\s*const \[confirmReset, setConfirmReset\]\s*=\s*\n?\s*useState\(false\);)/;

  const match = source.match(statePattern);
  if (!match) {
    fail('Could not find confirmReset state anchor.');
  }

  const block = `${match[1]}

  ${marker}
  const landingRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLElement | null>(null);

  useLayoutEffect(() => {
    const landing = landingRef.current;
    const content = contentRef.current;
    if (!landing || !content) return undefined;

    let frame = 0;

    const px = (value: string) =>
      Number.parseFloat(value) || 0;

    const fit = () => {
      window.cancelAnimationFrame(frame);

      frame = window.requestAnimationFrame(() => {
        landing.style.setProperty('--opfg-landing-scale', '1');

        const style = window.getComputedStyle(landing);
        const availableHeight = Math.max(
          1,
          landing.clientHeight
            - px(style.paddingTop)
            - px(style.paddingBottom),
        );
        const availableWidth = Math.max(
          1,
          landing.clientWidth
            - px(style.paddingLeft)
            - px(style.paddingRight),
        );

        const naturalHeight = Math.max(1, content.scrollHeight);
        const naturalWidth = Math.max(1, content.scrollWidth);

        const scale = Math.min(
          1,
          availableHeight / naturalHeight,
          availableWidth / naturalWidth,
        );

        landing.style.setProperty(
          '--opfg-landing-scale',
          scale.toFixed(4),
        );
      });
    };

    const observer = new ResizeObserver(fit);
    observer.observe(content);

    window.addEventListener('resize', fit);
    window.visualViewport?.addEventListener('resize', fit);
    fit();

    return () => {
      window.cancelAnimationFrame(frame);
      observer.disconnect();
      window.removeEventListener('resize', fit);
      window.visualViewport?.removeEventListener('resize', fit);
    };
  }, []);`;

  return source.replace(match[1], block);
}

function ensureRefs(source) {
  if (!source.includes('ref={landingRef}')) {
    const anchor = '<main className="opfg-landing">';
    if (!source.includes(anchor)) {
      fail('Could not find landing <main> anchor.');
    }

    source = source.replace(
      anchor,
      `<main
      ref={landingRef}
      className="opfg-landing"
    >`,
    );
  }

  if (!source.includes('ref={contentRef}')) {
    const anchor = '<section className="opfg-landing__content">';
    if (!source.includes(anchor)) {
      fail('Could not find landing content <section> anchor.');
    }

    source = source.replace(
      anchor,
      `<section
        ref={contentRef}
        className="opfg-landing__content"
      >`,
    );
  }

  return source;
}

function ensureLogoElement(source) {
  if (source.includes('className="opfg-landing__logo"')) return source;

  const anchor = `          <span className="opfg-landing__kicker">
            {translate('ui.landing.kicker')}
          </span>
`;

  if (!source.includes(anchor)) {
    fail('Could not find landing kicker anchor.');
  }

  return source.replace(
    anchor,
    `${anchor}          <img
            src={logoMark}
            alt=""
            aria-hidden="true"
            draggable={false}
            className="opfg-landing__logo"
          />
`,
  );
}

console.log('[landing-rework] repo:', ROOT);

// 1. Force the approved logo asset.
fs.mkdirSync(ASSET_DIR, { recursive: true });
fs.writeFileSync(LOGO, Buffer.from(LOGO_BASE64, 'base64'));
console.log(`[landing-rework] wrote ${path.relative(ROOT, LOGO)}`);

// 2. Make the landing component responsive to viewport height.
let tsx = read(TSX);
tsx = ensureReactHooks(tsx);
tsx = ensureLogoImport(tsx);
tsx = ensureViewportFitHook(tsx);
tsx = ensureRefs(tsx);
tsx = ensureLogoElement(tsx);
write(TSX, tsx);

// 3. Append/replace a deterministic CSS override layer.
let css = read(CSS);

const START = '/* OPFG LANDING VIEWPORT FIT START */';
const END = '/* OPFG LANDING VIEWPORT FIT END */';

const override = `${START}
.opfg-landing {
  --opfg-landing-scale: 1;

  width: 100%;
  height: 100dvh;
  min-height: 0;
  overflow: hidden;
  place-items: center;
  padding:
    max(1rem, var(--safe-area-top))
    max(1.25rem, var(--safe-area-right))
    max(1rem, var(--safe-area-bottom))
    max(1.25rem, var(--safe-area-left));
}

.opfg-landing__content {
  width: min(100%, 46rem);
  gap: clamp(0.9rem, 2vh, 1.75rem);
  transform: scale(var(--opfg-landing-scale));
  transform-origin: center;
  will-change: transform;
}

.opfg-landing__brand {
  width: 100%;
}

.opfg-landing__logo {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  width: clamp(7rem, 17vh, 10.5rem);
  max-width: 42vw;
  height: auto;
  margin:
    clamp(0.2rem, 0.7vh, 0.4rem)
    auto
    clamp(0.45rem, 1.1vh, 0.8rem);
  filter: drop-shadow(0 12px 26px rgb(0 0 0 / 0.4));
  pointer-events: none;
  user-select: none;
}

.opfg-landing__title {
  font-size: clamp(2.2rem, 6.8vh, 4.8rem);
}

.opfg-landing__tagline {
  margin-top: clamp(0.5rem, 1.3vh, 0.9rem);
  font-size: clamp(0.82rem, 1.7vh, 1.02rem);
}

.opfg-landing__continue {
  min-height: clamp(5rem, 11vh, 6.2rem);
}

/* Portrait ratio => mobile composition. */
@media (orientation: portrait) {
  .opfg-landing {
    padding:
      max(0.75rem, var(--safe-area-top))
      max(0.75rem, var(--safe-area-right))
      max(11.5rem, var(--safe-area-bottom))
      max(0.75rem, var(--safe-area-left));
  }

  .opfg-landing__content {
    width: min(100%, 30rem);
    gap: clamp(0.65rem, 1.5vh, 1rem);
  }

  .opfg-landing__brand {
    max-width: 28rem;
  }

  .opfg-landing__kicker {
    margin-bottom: 0.15rem;
    font-size: 0.62rem;
    letter-spacing: 0.2em;
  }

  .opfg-landing__logo {
    width: clamp(6.25rem, 27vw, 8.75rem);
    max-width: 34vw;
    margin-bottom: clamp(0.3rem, 0.8vh, 0.55rem);
  }

  .opfg-landing__title {
    font-size: clamp(1.95rem, 9.5vw, 3.35rem);
  }

  .opfg-landing__tagline {
    max-width: 26rem;
    margin-top: 0.5rem;
    font-size: clamp(0.76rem, 3vw, 0.92rem);
    line-height: 1.4;
  }

  .opfg-landing__primary {
    width: min(100%, 26rem);
    gap: 0.45rem;
  }

  .opfg-landing__new-primary {
    min-height: 3.4rem;
    padding-inline: 1.4rem;
    font-size: 0.9rem;
  }

  .opfg-landing__continue {
    min-height: 4.8rem;
    gap: 0.4rem;
    padding: 0.75rem 0.9rem;
  }

  .opfg-landing__continue-title {
    font-size: 0.92rem;
  }

  .opfg-landing__secondary {
    width: min(100%, 26rem);
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.4rem;
  }

  .opfg-landing__secondary-button {
    min-height: 2.5rem;
    gap: 0.3rem;
    padding-inline: 0.35rem;
    font-size: 0.64rem;
  }

  .opfg-landing__save-details {
    display: grid;
    gap: 0.12rem;
  }

  .opfg-landing__save-details > span[aria-hidden='true'] {
    display: none;
  }

  .opfg-landing__new-secondary {
    font-size: 0.67rem;
  }
}

/* Landscape ratio => classic composition. */
@media (orientation: landscape) {
  .opfg-landing__content {
    width: min(100%, 46rem);
  }

  .opfg-landing__secondary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (orientation: landscape) and (max-height: 42rem) {
  .opfg-landing__kicker {
    font-size: 0.62rem;
  }

  .opfg-landing__secondary-button {
    min-height: 2.75rem;
  }
}
${END}`;

const startIndex = css.indexOf(START);
const endIndex = css.indexOf(END);

if (startIndex >= 0 && endIndex >= startIndex) {
  css =
    css.slice(0, startIndex).trimEnd()
    + '\n\n'
    + override
    + '\n';
} else {
  css = css.trimEnd() + '\n\n' + override + '\n';
}

write(CSS, css);

console.log('\n[landing-rework] Done.');
console.log('[landing-rework] Next: npm run build');
